-- =============================================================================
-- 554 — LE CAHIER D'EXERCICES DE TLE (partie 26)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 554 --niveau Tle --fichiers musique.jumelles,sport.jumelles --suffixe 26 > supabase/contenu/554_exercices_tle_26.sql
--
-- 18 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   musique.jumelles         9 exercices · 3 chapitres
--   sport.jumelles           9 exercices · 3 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('b3da00cc-e1c2-50d6-b6ee-eaa62356acae'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Deux interprètes, une partition","competence":"lire-tableau","situation":"Deux pianistes jouent le même passage d’une même partition. Camille compare leurs choix dans un tableau et en déduit ce que décide un interprète.","documents":[{"id":"comp","type":"tableau","titre":"Le même passage, deux interprétations","colonnes":["Critère","Interprète A","Interprète B"],"lignes":[["Tempo (pulsations par minute)",60,80],["Durée du passage","3 min 00 s","2 min 15 s"],["Nuances","Très douces, peu de relief","Contrastées : le thème ressort"],["Phrasé","Notes très liées","Notes plus détachées"]],"enteteLignes":true,"source":"Données imaginées pour l’exercice"}],"questions":[{"enonce":"Touche **le tempo le plus rapide**.","aide":"Plus il y a de pulsations par minute, plus la musique va vite.","type":"zone","document":"comp","multiple":false},{"enonce":"De combien de secondes la version B est-elle plus courte que la version A ?","aide":"Passe les deux durées en secondes avant de soustraire : 3 min = 180 s.","type":"nombre","unite":"secondes"},{"enonce":"Relie chaque choix de l’interprète à ce qu’il change à l’écoute.","aide":"Le tableau compare le tempo, les nuances et le phrasé : relie chaque ligne à son effet.","type":"association","gauche":[{"id":"g0","texte":"Le tempo"},{"id":"g1","texte":"Les nuances"},{"id":"g2","texte":"Le phrasé"},{"id":"g3","texte":"L’instrument"}],"droite":[{"id":"d0","texte":"L’énergie, la respiration de la phrase"},{"id":"d1","texte":"Le sens : où la phrase respire"},{"id":"d2","texte":"Le relief, ce qui passe au premier plan"},{"id":"d3","texte":"La couleur, l’équilibre, la puissance"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"L’interprète B joue à **80** pulsations par minute, contre 60 pour A : c’est le tempo le plus rapide."},{"cle":{"type":"nombre","valeur":45,"tolerance":0},"affichage":"45 secondes","explication":"A dure 180 s, B dure 135 s : 180 − 135 = **45 secondes**."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"**Tempo** : énergie ; **nuances** : relief ; **phrasé** : sens de la phrase ; **instrument** : couleur et puissance. Un interprète ne « restitue » pas : il choisit."}]$ex$::jsonb),
  ('b3da00cc-e1c2-50d6-b6ee-eaa62356acae'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Bach avec les instruments de son temps","competence":"analyser-document","situation":"Un ensemble « historiquement informé » joue le même Bach qu’un grand orchestre moderne. Clara reçoit une fiche comparant les deux versions et doit retrouver laquelle est laquelle.","documents":[{"id":"versions","type":"tableau","titre":"Deux versions d’un même concerto","colonnes":["Critère","Version A","Version B"],"lignes":[["Diapason (la)","440 Hz","415 Hz"],["Cordes","En acier","En boyau"],["Effectif","60 musiciens","22 musiciens"],["Articulation","Appuyée, continue","Plus légère"]],"enteteLignes":true,"source":"Effectifs imaginés ; diapasons usuels"}],"questions":[{"enonce":"Les musiciens « historiquement informés » jouent sur des cordes anciennes. Touche **la case qui décrit leurs cordes**.","aide":"Ils utilisent des cordes en boyau, comme à l’époque de Bach.","type":"zone","document":"versions","multiple":false},{"enonce":"De combien de hertz le diapason de la version B est-il plus bas que celui de la version A ?","aide":"Lis les deux valeurs dans la ligne « Diapason », puis soustrais.","type":"nombre","unite":"Hz"},{"enonce":"Range chaque caractéristique : orchestre moderne ou pratique d’époque ?","aide":"Reprends les colonnes A et B du tableau.","type":"categories","categories":[{"id":"c0","texte":"Orchestre moderne"},{"id":"c1","texte":"Pratique d’époque"}],"items":[{"id":"i0","texte":"Effectif réduit"},{"id":"i1","texte":"Cordes en boyau"},{"id":"i2","texte":"Diapason à 440 Hz"},{"id":"i3","texte":"Cordes en acier"},{"id":"i4","texte":"Diapason plus bas"},{"id":"i5","texte":"Articulation appuyée et continue"}]},{"enonce":"Que montre le contraste entre les deux versions ?","aide":"Le même Bach devient méconnaissable : qu’est-ce que cela prouve ?","type":"choix","options":[{"id":"a","texte":"Une partition s’entend très différemment : aucune version n’est LA fidèle"},{"id":"b","texte":"Les deux versions sonnent de façon identique à l’oreille"},{"id":"c","texte":"La version A est la seule qui respecte vraiment la partition écrite"},{"id":"d","texte":"La version B est erronée à cause de son diapason plus bas que A"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"La **version B** joue sur des cordes en **boyau** : c’est la version historiquement informée. La version A, en acier, est celle de l’orchestre moderne."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 Hz","explication":"440 − 415 = **25 Hz** : le diapason ancien est plus bas qu’aujourd’hui."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c1","i5":"c0"}},"explication":"La musique **historiquement informée** rejoue le répertoire avec les moyens de l’époque : **diapason plus bas, cordes en boyau, effectifs réduits, articulation plus légère**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le même Bach devient méconnaissable : cela montre que **« la » version fidèle n’existe pas**. Chaque interprétation est un choix."}]$ex$::jsonb),
  ('b3da00cc-e1c2-50d6-b6ee-eaa62356acae'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Écouter deux fois, comparer","competence":"lire-graphique","situation":"Inès prépare une écoute active : elle compare le tempo de deux interprétations d’un même morceau, section par section. Elle note aussi comment organiser son écoute et comment en parler.","documents":[{"id":"tempo","type":"graphique","forme":"courbe","titre":"Tempo de deux interprétations","categories":["Début","Thème","Reprise","Fin"],"series":[{"nom":"Interprétation A","valeurs":[80,80,80,70],"teinte":"violet"},{"nom":"Interprétation B","valeurs":[72,84,66,50],"teinte":"corail"}],"axeY":{"titre":"Tempo","unite":"pulsations/min","min":40,"max":90,"pas":10},"axeX":{"titre":"Section du morceau"},"source":"Valeurs imaginées pour l’exercice"},{"id":"notes","type":"texte","genre":"article","titre":"Les notes d’Inès","auteur":"Notes écrites pour l’exercice","blocs":["Je compare deux interprétations du même passage : c’est le raccourci le plus efficace pour voir ce que décide un interprète.","Dans l’interprétation B, la dernière section est presque suspendue, alors qu’A garde presque le même tempo jusqu’au bout."],"source":"Notes écrites pour l’exercice"}],"questions":[{"enonce":"Touche **la section où les deux interprétations diffèrent le plus**.","aide":"Pour chaque section, calcule l’écart entre les deux tempos.","type":"zone","document":"tempo","multiple":false},{"enonce":"De combien de pulsations par minute l’interprétation B ralentit-elle entre la reprise et la fin ?","aide":"Lis la courbe de B pour la reprise, puis pour la fin.","type":"nombre","unite":"pulsations/min"},{"enonce":"Quelle phrase relève d’une écoute active, avec des mots d’analyse et non de goût ?","aide":"Une phrase d’analyse s’appuie sur ce qu’on entend (tempo, section), pas sur ce qu’on aime.","type":"choix","options":[{"id":"a","texte":"La version B est tout simplement la meilleure"},{"id":"b","texte":"B est triste, car le pianiste devait être triste"},{"id":"c","texte":"J’aime moins la version B que la version A"},{"id":"d","texte":"B ralentit nettement à la fin : la phrase paraît suspendue"}],"multiple":false},{"enonce":"Range chaque geste d’écoute : avant, pendant ou après ?","aide":"Avant : se préparer. Pendant : repérer les retours et les ruptures. Après : raconter.","type":"categories","categories":[{"id":"c0","texte":"Avant"},{"id":"c1","texte":"Pendant"},{"id":"c2","texte":"Après"}],"items":[{"id":"i0","texte":"Noter une rupture"},{"id":"i1","texte":"Noter un retour du thème"},{"id":"i2","texte":"Raconter ce que j’ai entendu avec des mots d’analyse"},{"id":"i3","texte":"Me demander ce que je vais chercher"},{"id":"i4","texte":"Choisir un repère : instrument, forme, retour de thème"},{"id":"i5","texte":"Comparer mes notes avec celles d’un camarade"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"Les écarts sont de 8, 4, 14 puis **20** pulsations par minute : c’est à la **fin** que les deux interprétations diffèrent le plus."},{"cle":{"type":"nombre","valeur":16,"tolerance":0},"affichage":"16 pulsations/min","explication":"B passe de 66 à 50 pulsations par minute : 66 − 50 = **16**."},{"cle":{"type":"choix","ids":["d"]},"explication":"La bonne phrase dit **ce qu’on a entendu**, avec des mots d’analyse (le tempo, la fin). Les autres expriment un goût ou une supposition sur la vie du musicien."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c2","i3":"c0","i4":"c0","i5":"c2"}},"explication":"**Avant** : on se prépare (que vais-je chercher ?). **Pendant** : on repère retours et ruptures. **Après** : on raconte ce qu’on a entendu, avec des mots d’analyse."}]$ex$::jsonb),
  ('8b23d2da-b660-50e4-9087-eac5b0615ca9'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois fins de phrase","competence":"analyser-document","situation":"Lina écoute trois phrases d’une chanson et note, pour chacune, comment elle se termine. Elle veut mettre un nom sur ce qu’elle ressent à la fin de chaque phrase.","documents":[{"id":"notes","type":"tableau","titre":"Le carnet d’écoute de Lina","colonnes":["Phrase","Ce que j’entends à la fin"],"lignes":[["Phrase 1","La dominante puis la tonique : la phrase se ferme"],["Phrase 2","On s’arrête sur la dominante : la phrase reste ouverte"],["Phrase 3","La dominante, puis un autre degré que la tonique : surprise"]],"enteteLignes":true,"source":"Notes d’écoute imaginées pour l’exercice"}],"questions":[{"enonce":"Touche **la phrase qui paraît achevée** à l’oreille.","aide":"Une phrase achevée se termine par la tonique, après la dominante.","type":"zone","document":"notes","multiple":false},{"enonce":"Donne à chaque fin de phrase le nom de sa cadence.","aide":"Parfaite : dominante puis tonique. Suspensive : on s’arrête sur la dominante. Rompue : un autre degré.","type":"association","gauche":[{"id":"g0","texte":"Phrase 1"},{"id":"g1","texte":"Phrase 2"},{"id":"g2","texte":"Phrase 3"}],"droite":[{"id":"d0","texte":"Cadence suspensive"},{"id":"d1","texte":"Cadence rompue"},{"id":"d2","texte":"Cadence parfaite"}]},{"enonce":"Quel effet produit la cadence de la phrase 3 ?","aide":"La dominante promet la tonique, mais elle ne vient pas.","type":"choix","options":[{"id":"a","texte":"L’attente : la phrase reste ouverte"},{"id":"b","texte":"L’achèvement : la phrase se ferme"},{"id":"c","texte":"La surprise : l’attente est déjouée"},{"id":"d","texte":"Un silence qui annonce la fin du morceau"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0"]},"explication":"La **phrase 1** se termine par dominante → tonique : l’oreille entend la phrase se fermer. C’est la cadence parfaite."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**Phrase 1** : cadence parfaite (dominante → tonique) ; **phrase 2** : cadence suspensive (arrêt sur la dominante) ; **phrase 3** : cadence rompue (dominante → autre degré)."},{"cle":{"type":"choix","ids":["c"]},"explication":"Dans une **cadence rompue**, la dominante n’est pas suivie de la tonique : l’attente est **déjouée**, d’où la surprise."}]$ex$::jsonb),
  ('8b23d2da-b660-50e4-9087-eac5b0615ca9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quatre textures sur un piano-roll","competence":"observer-schema","situation":"Un logiciel de musique affiche chaque ligne mélodique sous forme de barres : l’abscisse est le temps, la hauteur est la hauteur du son. Raphaël a affiché quatre extraits de textures différentes.","documents":[{"id":"sch","type":"schema","titre":"Quatre extraits, quatre textures","largeur":340,"hauteur":250,"elements":[{"forme":"rect","x":14,"y":10,"l":148,"h":84,"teinte":"gris","motif":"clair"},{"forme":"rect","x":22,"y":36,"l":18,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":42,"y":26,"l":12,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":56,"y":20,"l":18,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":76,"y":30,"l":12,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":90,"y":40,"l":24,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":116,"y":32,"l":14,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":132,"y":24,"l":18,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":25,"y":48,"l":16,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":45,"y":38,"l":10,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":59,"y":32,"l":16,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":79,"y":42,"l":10,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":93,"y":52,"l":22,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":119,"y":44,"l":12,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":135,"y":36,"l":16,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":20,"y":60,"l":19,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":40,"y":50,"l":13,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":54,"y":44,"l":19,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":74,"y":54,"l":13,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":88,"y":64,"l":25,"h":6,"teinte":"violet","motif":"plein"},{"forme":"rect","x":