tif":"plein"},{"forme":"rect","x":280,"y":184,"l":14,"h":6,"teinte":"gris","motif":"plein"},{"forme":"rect","x":296,"y":152,"l":18,"h":6,"teinte":"gris","motif":"plein"},{"forme":"rect","x":296,"y":164,"l":18,"h":6,"teinte":"gris","motif":"plein"},{"forme":"rect","x":296,"y":176,"l":18,"h":6,"teinte":"gris","motif":"plein"},{"forme":"rect","x":68,"y":98,"l":40,"h":20,"teinte":"violet","motif":"clair","texte":"1","id":"z1","zone":true},{"forme":"rect","x":232,"y":98,"l":40,"h":20,"teinte":"violet","motif":"clair","texte":"2","id":"z2","zone":true},{"forme":"rect","x":68,"y":214,"l":40,"h":20,"teinte":"violet","motif":"clair","texte":"3","id":"z3","zone":true},{"forme":"rect","x":232,"y":214,"l":40,"h":20,"teinte":"violet","motif":"clair","texte":"4","id":"z4","zone":true}],"legende":[{"teinte":"violet","motif":"plein","texte":"Une ligne mélodique"},{"teinte":"gris","motif":"plein","texte":"Un accord (plusieurs sons)"}]}],"questions":[{"enonce":"Touche **le numéro de la texture qui superpose plusieurs lignes mélodiques indépendantes**.","aide":"Cherche l’extrait où trois lignes de couleurs différentes ne suivent pas le même dessin.","type":"zone","document":"sch","multiple":false},{"enonce":"Touche **le numéro de la texture où une seule mélodie est soutenue par des blocs d’accords**.","aide":"Les accords sont les blocs gris, placés sous la mélodie violette.","type":"zone","document":"sch","multiple":false},{"enonce":"Combien de lignes mélodiques compte l’extrait 3 ?","aide":"Compte les couleurs différentes dans l’extrait 3.","type":"nombre","unite":"lignes"},{"enonce":"Relie chaque texture à un exemple.","aide":"La monodie est la plus simple : une seule ligne, sans accompagnement.","type":"association","gauche":[{"id":"g0","texte":"Monodie"},{"id":"g1","texte":"Homophonie"},{"id":"g2","texte":"Polyphonie"},{"id":"g3","texte":"Hétérophonie"}],"droite":[{"id":"d0","texte":"Chant grégorien"},{"id":"d1","texte":"Musiques traditionnelles"},{"id":"d2","texte":"Chanson, choral"},{"id":"d3","texte":"Fugue, motet"}]}]}$ex$::jsonb,
